<?php
declare(strict_types=1);namespace App\Modules\SupplierPayments\Validators;use App\Core\Exceptions\ValidationException;use App\Modules\SupplierPayments\DTOs\SupplierPaymentData;final class SupplierPaymentValidator{public const METHODS=['cash','bank_transfer','cheque','other'];public function validate(array$i):SupplierPaymentData{$e=[];$invoice=max(0,(int)($i['supplier_invoice_id']??0));if($invoice<1)$e['supplier_invoice_id'][]='اختر فاتورة مورد معتمدة.';$date=trim((string)($i['payment_date']??''));$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)$e['payment_date'][]='تاريخ الدفع غير صالح.';$amount=trim((string)($i['amount']??''));if(!preg_match('/^(?:0*[1-9]\d*)(?:\.\d{1,2})?$|^0*\.\d{1,2}$/',$amount)||preg_match('/^0*(?:\.0{1,2})?$/',$amount))$e['amount'][]='المبلغ يجب أن يكون أكبر من صفر وبدقتين عشريتين.';$method=(string)($i['payment_method']??'');if(!in_array($method,self::METHODS,true))$e['payment_method'][]='طريقة الدفع غير صالحة.';$reference=$this->nullable($i['reference']??null);if($reference!==null&&mb_strlen($reference)>190)$e['reference'][]='المرجع أطول من المسموح.';$notes=$this->nullable($i['notes']??null);if($notes!==null&&mb_strlen($notes)>5000)$e['notes'][]='الملاحظات أطول من المسموح.';if($e)throw new ValidationException($e);[$w,$f]=array_pad(explode('.',ltrim($amount,'0')?:'0',2),2,'');return new SupplierPaymentData($invoice,$date,($w===''?'0':$w).'.'.str_pad($f,2,'0'),$method,$reference,$notes);}private function nullable(mixed$v):?string{$v=trim((string)$v);return$v===''?null:$v;}}
